]

from collections import deque

def get_component(grid, start_pos):
    rows, cols = len(grid), len(grid[0])
    value = grid[start_pos[0]][start_pos[1]]
    if value == 0:
        return set()
    visited = set()
    queue = deque([start_pos])
    visited.add(start_pos)
    component = set()
    while queue:
        r, c = queue.popleft()
        component.add((r, c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == value:
                visited.add((nr, nc))
                queue.append((nr, nc))
    return component

rows, cols = len(grid), len(grid[0])
color_cells = {}
for r in range(rows):
    for c in range(cols):
        if grid[r][c] != 0:
            if grid[r][c] not in color_cells:
                color_cells[grid[r][c]] = []
            color_cells[grid[r][c]].append((r, c))

result = [[0]*cols for _ in range(rows)]

for color, cells in sorted(color_cells.items()):
    # Get all components for this color
    visited = set()
    for cell in cells:
        if cell not in visited:
            comp = get_component(grid, cell)
            visited.update(comp)
            # Find rightmost column in this component
            max_c = max(c for (r, c) in comp)
            # Calculate shift: new right = cols - 1
            shift = (cols - 1) - max_c
            for r, c in comp:
                nc = c + shift
                if 0 <= nc < cols:
                    result[r][nc] = color

print("Shifted grid:")
for row in result:
    print(row)

